1	package com.loja.checkout.domain;
2	
3	import com.loja.checkout.web.RequisicaoCheckout;
4	import com.loja.checkout.web.RequisicaoCheckout.ItemRequest;
5	import com.loja.checkout.web.RespostaResumo;
6	import java.math.BigDecimal;
7	import java.util.ArrayList;
8	import java.util.List;
9	import java.util.Optional;
10	import org.springframework.stereotype.Service;
11	
12	/**
13	 * Orquestra o cálculo do resumo. O que é igual a todos os casos mora aqui: a
14	 * ordem do cálculo e a ordem das validações (devolvendo o primeiro problema).
15	 * O que muda de caso para caso delega para as famílias (entrega, cupom, clube,
16	 * pagamento) e para a região.
17	 */
18	@Service
19	public class CalculadoraResumo {
20	
21	    public RespostaResumo calcular(RequisicaoCheckout req) {
22	        // 1. Carrinho
23	        Pedido pedido = construirPedido(req.itens());
24	
25	        // 2. a 4. Dados obrigatórios do pedido, na ordem do enunciado
26	        NivelClube nivel = exigir(NivelClube.fromCodigo(req.nivelClube()), "NIVEL_CLUBE_INVALIDO");
27	        Regiao regiao = exigir(Regiao.fromCodigo(req.regiao()), "REGIAO_INVALIDA");
28	        ModalidadeEntrega modalidade = exigir(ModalidadeEntrega.fromCodigo(req.modalidadeEntrega()), "MODALIDADE_INVALIDA");
29	
30	        // 5. Modalidade existe mas não atende o pedido
31	        if (!modalidade.atende(pedido.pesoTotal())) {
32	            throw new CheckoutException("MODALIDADE_INDISPONIVEL");
33	        }
34	
35	        // 6. e 7. Cupom (opcional)
36	        Cupom cupom = resolverCupom(req.cupom(), pedido);
37	
38	        // 8. e 9. Forma de pagamento e parcelas
39	        FormaPagamento forma = exigir(FormaPagamento.fromCodigo(req.formaPagamento()), "FORMA_PAGAMENTO_INVALIDA");
40	        int parcelas = req.parcelas() == null ? 1 : req.parcelas();
41	        if (!forma.parcelasPermitidas(parcelas)) {
42	            throw new CheckoutException("PARCELAMENTO_INVALIDO");
43	        }
44	
45	        // Cálculo do total do pedido
46	        BigDecimal subtotal = pedido.subtotalProdutos();
47	        BigDecimal frete = nivel.freteGratis() ? Dinheiro.ZERO : modalidade.frete(pedido.pesoTotal());
48	        BigDecimal descontoCupom = cupom == null ? Dinheiro.ZERO : cupom.desconto(pedido, frete);
49	        BigDecimal seguro = regiao.seguro(subtotal);
50	        BigDecimal totalPedido = subtotal.subtract(descontoCupom).add(frete).add(seguro);
51	
52	        // 10. Forma existe mas não atende o pedido (ex.: boleto acima de R$ 1.000)
53	        if (!forma.atende(totalPedido)) {
54	            throw new CheckoutException("FORMA_PAGAMENTO_INDISPONIVEL");
55	        }
56	
57	        ResultadoPagamento pagamento = forma.calcular(totalPedido, parcelas);
58	        BigDecimal ajuste = pagamento.totalFinal().subtract(totalPedido);
59	
60	        return new RespostaResumo(
61	                subtotal,
62	                descontoCupom,
63	                frete,
64	                modalidade.prazoDias(),
65	                seguro,
66	                ajuste,
67	                pagamento.totalFinal(),
68	                parcelas,
69	                pagamento.valorParcela(),
70	                nivel.credito(subtotal),
71	                nivel.brinde(subtotal));
72	    }
73	
74	    private Pedido construirPedido(List<ItemRequest> itens) {
75	        if (itens == null || itens.isEmpty()) {
76	            throw new CheckoutException("PEDIDO_INVALIDO");
77	        }
78	        BigDecimal subtotal = BigDecimal.ZERO;
79	        BigDecimal peso = BigDecimal.ZERO;
80	        List<Pedido.Item> itensPedido = new ArrayList<>();
81	        for (ItemRequest item : itens) {
82	            if (item.precoUnitario() == null || item.quantidade() == null || item.pesoKg() == null
83	                    || item.precoUnitario().signum() <= 0 || item.quantidade() <= 0 || item.pesoKg().signum() <= 0) {
84	                throw new CheckoutException("PEDIDO_INVALIDO");
85	            }
86	            BigDecimal qtd = BigDecimal.valueOf(item.quantidade());
87	            subtotal = subtotal.add(item.precoUnitario().multiply(qtd));
88	            peso = peso.add(item.pesoKg().multiply(qtd));
89	            itensPedido.add(new Pedido.Item(item.precoUnitario(), item.quantidade()));
90	        }
91	        return new Pedido(Dinheiro.arredonda(subtotal), peso, itensPedido);
92	    }
93	
94	    private Cupom resolverCupom(String codigo, Pedido pedido) {
95	        if (codigo == null) {
96	            return null;
97	        }
98	        Cupom cupom = exigir(Cupom.fromCodigo(codigo), "CUPOM_INVALIDO");
99	        if (!cupom.aplicavel(pedido)) {
100	            throw new CheckoutException("CUPOM_NAO_APLICAVEL");
101	        }
102	        return cupom;
103	    }
104	
105	    private static <T> T exigir(Optional<T> valor, String codigoErro) {
106	        return valor.orElseThrow(() -> new CheckoutException(codigoErro));
107	    }
108	}
