1	package com.loja.checkout.domain;
2	
3	import java.math.BigDecimal;
4	import java.util.Arrays;
5	import java.util.Optional;
6	
7	/**
8	 * Cada forma de pagamento ajusta o total do seu jeito, tem suas parcelas
9	 * permitidas e suas limitações.
10	 */
11	public enum FormaPagamento {
12	
13	    PIX {
14	        @Override
15	        public boolean parcelasPermitidas(int parcelas) {
16	            return parcelas == 1;
17	        }
18	
19	        @Override
20	        public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
21	            BigDecimal desconto = Dinheiro.arredonda(totalPedido.multiply(new BigDecimal("0.05")));
22	            return aVista(totalPedido.subtract(desconto));
23	        }
24	    },
25	    BOLETO {
26	        @Override
27	        public boolean parcelasPermitidas(int parcelas) {
28	            return parcelas == 1;
29	        }
30	
31	        @Override
32	        public boolean atende(BigDecimal totalPedido) {
33	            return totalPedido.compareTo(LIMITE_BOLETO) <= 0;
34	        }
35	
36	        @Override
37	        public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
38	            return aVista(totalPedido.add(TARIFA_BOLETO));
39	        }
40	    },
41	    CARTAO {
42	        @Override
43	        public boolean parcelasPermitidas(int parcelas) {
44	            return parcelas >= 1 && parcelas <= 12;
45	        }
46	
47	        @Override
48	        public ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas) {
49	            if (parcelas <= PARCELAS_SEM_JUROS) {
50	                BigDecimal valorParcela = totalPedido.divide(BigDecimal.valueOf(parcelas), 2,
51	                        java.math.RoundingMode.HALF_EVEN);
52	                return new ResultadoPagamento(totalPedido, valorParcela);
53	            }
54	            // Tabela Price: parcela = total * taxa / (1 - (1 + taxa)^-n)
55	            double taxa = TAXA_CARTAO_MENSAL;
56	            double fator = 1 - Math.pow(1 + taxa, -parcelas);
57	            double parcela = totalPedido.doubleValue() * taxa / fator;
58	            BigDecimal valorParcela = Dinheiro.arredonda(BigDecimal.valueOf(parcela));
59	            BigDecimal totalFinal = Dinheiro.arredonda(valorParcela.multiply(BigDecimal.valueOf(parcelas)));
60	            return new ResultadoPagamento(totalFinal, valorParcela);
61	        }
62	    };
63	
64	    private static final BigDecimal LIMITE_BOLETO = new BigDecimal("1000.00");
65	    private static final BigDecimal TARIFA_BOLETO = new BigDecimal("3.49");
66	    private static final int PARCELAS_SEM_JUROS = 3;
67	    private static final double TAXA_CARTAO_MENSAL = 0.0199;
68	
69	    public abstract boolean parcelasPermitidas(int parcelas);
70	
71	    /** A forma atende este total de pedido? Por padrão, sim. */
72	    public boolean atende(BigDecimal totalPedido) {
73	        return true;
74	    }
75	
76	    public abstract ResultadoPagamento calcular(BigDecimal totalPedido, int parcelas);
77	
78	    /** Pagamento à vista: a parcela única é o próprio valor final. */
79	    private static ResultadoPagamento aVista(BigDecimal valorFinal) {
80	        BigDecimal finalArredondado = Dinheiro.arredonda(valorFinal);
81	        return new ResultadoPagamento(finalArredondado, finalArredondado);
82	    }
83	
84	    public static Optional<FormaPagamento> fromCodigo(String codigo) {
85	        return Arrays.stream(values()).filter(f -> f.name().equals(codigo)).findFirst();
86	    }
87	}
